        Colors[ 0] := 'FFFFFF'; // White
        Colors[ 1] := 'FF0000'; // Red
        Colors[ 2] := '00AA00'; // Green
        Colors[ 3] := 'FFEE00'; // Yellow
        Colors[ 4] := 'AA00CC'; // Violett
        Colors[ 5] := '0033EE'; // Blue
        Colors[ 6] := 'FFFFAA'; // Cream
        Colors[ 7] := 'FF66DD'; // LightViolett
        Colors[ 8] := '0077FF'; // LightBlue
        Colors[ 9] := '777777'; // Gray
        Colors[10] := 'FF6000'; // Orange
        Colors[11] := '00DD00'; // LightGreen

        H := 0.7;
        R := H * 0.725;

        s3 := sqrt(3);
        s5 := sqrt(5);

        D := R * sqrt((5 - s5) / 10);

        for i := 0 to 59 do begin
            x[i] := R * cos(2 * Pi / 60 * (i+5));
            y[i] := R * sin(2 * Pi / 60 * (i+5));
        end;
